6	/// <summary>
7	/// Thrown by <see cref="SystemBuilder.Build"/> when the declared topology has one or
8	/// more error-severity violations. Carries every diagnostic found — not just the first —
9	/// so a SystemHost run reports the whole picture at once.
10	/// </summary>
11	public sealed class TopologyValidationException : Exception
12	{
13	    /// <summary>All diagnostics found, including warnings.</summary>
14	    public IReadOnlyList<TopologyDiagnostic> Diagnostics { get; }
15	
16	    /// <summary>Creates the exception with no diagnostics.</summary>
17	    public TopologyValidationException()
18	    {
19	        Diagnostics = [];
20	    }
21	
22	    /// <summary>Creates the exception with a message and no diagnostics.</summary>
23	    /// <param name="message">The exception message.</param>
24	    public TopologyValidationException(string message)
25	        : base(message)
26	    {
27	        Diagnostics = [];
28	    }
29	
30	    /// <summary>Creates the exception with a message, an inner exception, and no diagnostics.</summary>
31	    /// <param name="message">The exception message.</param>
32	    /// <param name="innerException">The causing exception.</param>
33	    public TopologyValidationException(string message, Exception innerException)
34	        : base(message, innerException)
35	    {
36	        Diagnostics = [];
37	    }
38	
39	    /// <summary>Creates the exception from the full diagnostic list.</summary>
40	    /// <param name="diagnostics">All diagnostics found while validating the topology.</param>
41	    public TopologyValidationException(IReadOnlyList<TopologyDiagnostic> diagnostics)
42	        : base(BuildMessage(diagnostics))
43	    {
44	        Diagnostics = diagnostics;
45	    }
46	
47	    private static string BuildMessage(IReadOnlyList<TopologyDiagnostic> diagnostics)
48	    {
49	        var errorCount = diagnostics.Count(d => d.Severity == DiagnosticSeverity.Error);
50	        var builder = new StringBuilder();
51	        builder.Append(CultureInfo.InvariantCulture, $"The system topology is invalid ({errorCount} error(s)):");
52	        foreach (var diagnostic in diagnostics)
53	        {
54	            builder.AppendLine();
55	            builder.Append(CultureInfo.InvariantCulture, $"  {diagnostic.Code} [{diagnostic.Severity}]");
56	            if (diagnostic.Target is not null)
57	            {
58	                builder.Append(CultureInfo.InvariantCulture, $" {diagnostic.Target}:");
59	            }
60	
61	            builder.Append(CultureInfo.InvariantCulture, $" {diagnostic.Message}");
62	        }
63	
64	        return builder.ToString();
65	    }
66	}
