49	/// <summary>ITP103: one topic must not be used with two different event contract types.</summary>
50	internal sealed class TopicContractConflictRule : ITopologyRule
51	{
52	    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
53	    {
54	        var usages = context.Builder.Components.SelectMany(TopicUsages);
55	
56	        var conflicts = usages
57	            .GroupBy(t => (t.PubSubName, t.TopicName))
58	            .Where(g => g.Select(t => t.ContractType).Distinct().Count() > 1);
59	
60	        foreach (var group in conflicts)
61	        {
62	            var contracts = string.Join(
63	                ", ",
64	                group.Select(t => t.ContractType.FullName ?? t.ContractType.Name).Distinct().Order(StringComparer.Ordinal));
65	            yield return new TopologyDiagnostic(
66	                "ITP103",
67	                DiagnosticSeverity.Error,
68	                $"The topic '{group.Key.TopicName}' on pubsub '{group.Key.PubSubName}' is declared with conflicting contract types: {contracts}.",
69	                group.Key.TopicName);
70	        }
71	    }
