87	/// <summary>ITP104: one connector name must not be declared with two different transports.</summary>
88	internal sealed class ConnectorConflictRule : ITopologyRule
89	{
90	    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
91	    {
92	        var usages = context.Builder.Components.SelectMany(ConnectorUsages);
93	
94	        foreach (var group in usages.GroupBy(c => c.Name, StringComparer.Ordinal))
95	        {
96	            var transports = group
97	                .Select(c => (Local: c.Transport, Deployed: c.DeployedTransport))
98	                .Distinct()
99	                .ToArray();
100	            if (transports.Length > 1)
101	            {
102	                var transportTypes = transports
103	                    .Select(t => t.Deployed is null
104	                        ? t.Local.DaprType
105	                        : $"{t.Local.DaprType} (deployed: {t.Deployed.DaprType})")
106	                    .Distinct(StringComparer.Ordinal)
107	                    .Order(StringComparer.Ordinal);
108	                yield return new TopologyDiagnostic(
109	                    "ITP104",
110	                    DiagnosticSeverity.Error,
111	                    $"The connector '{group.Key}' is declared with conflicting transports: {string.Join(", ", transportTypes)}.",
112	                    group.Key);
113	            }
114	        }
115	    }
