126	/// <summary>
127	/// ITP211: an explicitly declared deployed transport must support every connector direction
128	/// used by the component. A connector without a deployed transport continues to use its local
129	/// transport for deployment and needs no additional validation.
130	/// </summary>
131	internal sealed class DeployedTransportCapabilityRule : ITopologyRule
132	{
133	    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
134	    {
135	        foreach (var component in context.Builder.Components)
136	        {
137	            foreach (var (connector, direction) in component.ConnectorCalls)
138	            {
139	                var transport = connector.DeployedTransport;
140	                if (transport is null || Supports(direction, transport))
141	                {
142	                    continue;
143	                }
144	
145	                var operation = direction == Intropy.Topology.Model.ConnectorDirection.In ? "From" : "To";
146	                var capability = direction == Intropy.Topology.Model.ConnectorDirection.In ? "input" : "output";
147	                yield return new TopologyDiagnostic(
148	                    "ITP211",
149	                    DiagnosticSeverity.Error,
150	                    $"The connector '{connector.Name}' declares deployed transport '{transport.DaprType}', which does not support {capability} required by {operation}.",
151	                    component.Name);
152	            }
153	        }
154	    }
155	
156	    private static bool Supports(Intropy.Topology.Model.ConnectorDirection direction, Transport transport) =>
157	        direction == Intropy.Topology.Model.ConnectorDirection.In ? transport.SupportsInput : transport.SupportsOutput;
158	}
